float waterlevel = 0.0;        // height of the water
float wavegain   = 0.3;       // change to adjust the general water wave level
float large_waveheight = 1.0; // change to adjust the "heavy" waves (set to 0.0 to have a very still ocean :)
float small_waveheight = 2.0; // change to adjust the small waves

vec3 fogcolor    = vec3(1.0, 0.9725, 0.898);              
vec3 skybottom   = vec3(1.0, 0.9725, 0.9176);
vec3 skytop      = vec3(0.5882, 0.6549, 0.8235);
vec3 reflskycolor= vec3(0.3961, 0.4157, 0.5255);
vec3 watercolor  = vec3(0.251, 0.3451, 0.3608);

vec3 light       = normalize( vec3(  0.1, 0.25,  0.9 ) );

//start hash
uvec3 k = uvec3(0x456789abu, 0x6789ab45u, 0x89ab4567u);
uvec3 u = uvec3(1, 2, 3);
const uint UINT_MAX = 0xffffffffu;
uvec2 uhash22(uvec2 n){
    n ^= (n.yx << u.xy);
    n ^= (n.yx >> u.xy);
    n *= k.xy;
    n ^= (n.yx << u.xy);
    return n * k.xy;
}
uvec3 uhash33(uvec3 n){
    n ^= (n.yzx << u);
    n ^= (n.yzx >> u);
    n *= k;
    n ^= (n.yzx << u);
    return n * k;
}

//start pnoise
float gtable2(vec2 lattice, vec2 p){
    uvec2 n = floatBitsToUint(lattice);
    uint ind = uhash22(n).x >> 29;
    float u = 0.92387953 * (ind < 4u ? p.x : p.y);  //0.92387953 = cos(pi/8)
    float v = 0.38268343 * (ind < 4u ? p.y : p.x);  //0.38268343 = sin(pi/8)
    return ((ind & 1u) == 0u ? u : -u) + ((ind & 2u) == 0u? v : -v);
}
float pnoise21(vec2 p){
    vec2 n = floor(p);
    vec2 f = fract(p);
    float[4] v;
    for (int j = 0; j < 2; j ++){
        for (int i = 0; i < 2; i++){
            v[i+2*j] = gtable2(n + vec2(i, j), f - vec2(i, j));
        }
    }
    f = f * f * f * (10.0 - 15.0 * f + 6.0 * f * f);
    return 0.5 * mix(mix(v[0], v[1], f[0]), mix(v[2], v[3], f[0]), f[1]) + 0.5;
}
float gtable3(vec3 lattice, vec3 p){// latticeは格子点の位置、pは位置ベクトル
    uvec3 n = floatBitsToUint(lattice);//格子点の値をビット列に変換
    uint ind = uhash33(n).x >> 28; //ハッシュ値の桁を落とす
    float u = ind < 8u ? p.x : p.y;
    float v = ind < 4u ? p.y : ind == 12u || ind == 14u ? p.x : p.z;
    return ((ind & 1u) == 0u? u: -u) + ((ind & 2u) == 0u? v : -v);
}
float pnoise31(vec3 p){
    vec3 n = floor(p);
    vec3 f = fract(p);
    float[8] v;
    for (int k = 0; k < 2; k++ ){
        for (int j = 0; j < 2; j++ ){
            for (int i = 0; i < 2; i++){
                v[i+2*j+4*k] = gtable3(n + vec3(i, j, k), f - vec3(i, j, k)) * 0.70710678; // 0.70710678 = 1.0 / sqrt(2.0)
            }

        }
    }
    f = f * f * f * (10.0 - 15.0 * f + 6.0 * f * f);
    float[2] w;
    for (int i = 0; i < 2; i++){
        w[i] = mix(mix(v[4*i], v[4*i+1], f[0]), mix(v[4*i+2], v[4*i+3], f[0]), f[1]);
    }
    return 0.5 * mix(w[0], w[1], f[2]) + 0.5;
}
//end pnoise


mat3 m = mat3( 0.00,  1.60,  1.20, -1.60,  0.72, -0.96, -1.20, -0.96,  1.28 );

// Fractional Brownian motion
float fbm31( vec3 p )
{
  float f = 0.5000*pnoise31( p ); p = m*p*1.1;
  f += 0.2500*pnoise31( p ); p = m*p*1.2;
  f += 0.1666*pnoise31( p ); p = m*p;
  f += 0.0834*pnoise31( p );
  return f;
}

mat2 m2 = mat2(1.6,-1.2,1.2,1.6);

// Fractional Brownian motion
float fbm21( vec2 p )
{
  float f = 0.5000*pnoise21( p ); p = m2*p;
  f += 0.2500*pnoise21( p ); p = m2*p;
  f += 0.1666*pnoise21( p ); p = m2*p;
  f += 0.0834*pnoise21( p );
  return f;
}


// heightMapTracingのための水面の計算
float water( vec2 p )
{
  float height = waterlevel;

  vec2 shift1 = 0.001*vec2( iTime*160.0*2.0, iTime*120.0*2.0 );
  vec2 shift2 = 0.001*vec2(iTime*190.0*2.0, -iTime*130.0*2.0 );

  // coarse crossing 'ocean' waves...
  float wave = 0.0;
  wave += sin(p.x*0.021  + shift2.x)*4.5;
  wave += sin(p.x*0.0172+p.y*0.010 + shift2.x*1.121)*4.0;
  wave -= sin(p.x*0.00104+p.y*0.005 + shift2.x*0.121)*4.0;
  // ...added by some smaller faster waves...
  wave += sin(p.x*0.02221+p.y*0.01233+shift2.x*3.437)*5.0;
  wave += sin(p.x*0.03112+p.y*0.01122+shift2.x*4.269)*2.5 ;
  wave *= large_waveheight;
  wave -= fbm21(p*0.004-shift2*.5)*small_waveheight*24.;
  // ...added by some distored random waves (which makes the water looks like water :)

  float amp = 6.*small_waveheight;
  shift1 *= .3;
  for (int i=0; i<2; i++)
  {
    wave -= abs(sin((pnoise21(p*0.01+shift1)-.5)*3.14))*amp;
    amp *= .51;
    shift1 *= 1.841;
    p *= m2*0.9331;
  }

  height += wave;
  return height;
}


// 霧のレイトレーシング
float trace_fog(in vec3 rStart, in vec3 rDirection )
{
  // 雲の動きのシミュレート
  vec2 shift = vec2( iTime*80.0, iTime*60.0 );
  float sum = 0.0;
  float q2 = 0., q3 = 0.;
  for (int q=0; q<5; q++)
  {
    float c = (q2+350.0-rStart.y) / rDirection.y;// cloud distance
    vec3 cpos = rStart + c*rDirection + vec3(831.0, 321.0+q3-shift.x*0.2, 1330.0+shift.y*3.0); // cloud position
    float alpha = smoothstep(0.5, 1.0, fbm31( cpos*0.0015 )); // cloud density
	  sum += (1.0-sum)*alpha; // alpha saturation
    if (sum>0.98)
        break;
    q2 += 120.;
    q3 += 0.15;
  }

  return clamp( 1.0-sum, 0.0, 1.0 );
}

bool trace(in vec3 rStart, in vec3 rDirection, in float sundot, out float dist)
{
  // rayのスタート位置のy軸から水面までの高さ
  float height = 20.0;

  // レイが進んだ距離
  float traceDist = 0.0;

  // レイが一度に進むステップのサイズ
  float stepSize = 1.0;

  // 現在のレイの位置
  vec3 p = rStart;

  for( int i=0; i< 25; i++ )
  {
    // traceDistで遠くを描画し始めたらstepSizeの増分を加速させる
    if( traceDist>500.0 ) 
      stepSize = 2.0;
    else if( traceDist>800.0 ) 
      stepSize = 5.0;
    else if( traceDist>1000.0 ) 
      stepSize = 12.0;

    // 現在のrayの位置を計算
    p = rStart + traceDist * rDirection;

    // 現在の例から水面までの高さを出す。
    height = p.y - water(p.xz);

    // 高さが水面と限りなく近い、もしくは水面の中に入っていたら水面を描画するのでtrueを返す
    if( height<0.1 )
    {
      dist = traceDist; 
      return true;
    }

    // 高さが行きすぎてる場合があれば、forの処理をやめる
    if( p.y>450.0 )
      break;

    // 空の場合は考慮の必要がないのでステップサイズを上げる
    if(rDirection.y > 0.0)
      traceDist += 30.0 * stepSize;
    else
      traceDist += max(1.0,1.0*height)*stepSize;
  }

  dist = traceDist; 
  if (height<0.1)
   return true;
  return false;
}


vec3 camera( float time )
{
  return vec3( 500.0 * sin(1.5+1.57*time), 0.0, 1200.0*time );
}

float posteffect(vec2 uv, float scale, float speed) {
    return fbm21(uv * speed * scale);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
  // いつもの
  vec2 xy = -1.0 + 2.0*fragCoord.xy / iResolution.xy;

  float time = (iTime+13.5+44.)*.2;
  vec3 campos = camera( time );
  vec3 camtar = camera( time + 0.2 );
  // マウスのy座標を[0, 1]の範囲にスケーリング
  float mouseYNormalized = 2.0 * (iMouse.y / iResolution.y) -1.0;
  // マウスの位置に基づいてカメラのy座標を設定
  campos.y = max(waterlevel+30.0, waterlevel+90.0 + 60.0*mouseYNormalized*2.0);
  camtar.y = campos.y*0.5;

  // マウスのx座標を[-1, 1]の範囲にスケーリング
  float mouseXNormalized = 2.0 * (iMouse.x / iResolution.x) - 1.0;
  // マウスの位置に基づいてroll値を設定
  float roll = 0.54 * sin(mouseXNormalized);
  // カメラの視点方向ベクトル
  vec3 camwatch = normalize(camtar-campos);
  // カメラの傾きベクトル
  vec3 camrotate = vec3(sin(roll), cos(roll),0.0);
  // カメラの視点方向と傾きのクロス積からカメラの上方向のベクトルをとる
  vec3 camup = normalize(cross(camwatch,camrotate));

  // カメラの上方向と見ている方向の外積から右方向のベクトルをとる（camrotateと違いz軸の考慮がされる）
  vec3 camright = normalize(cross(camup,camwatch));

  // ここで抽象画風のfbmを使ったエフェクト
  xy.x += posteffect(xy, 7.0, 2.6) * 0.5;
  xy.y += posteffect(xy, 8.0, 2.7) * 0.5;

  //　rayの向き
  vec3 raydirection = normalize( xy.x*camup + xy.y*camright + 1.6*camwatch );

  // 太陽光の写像を描画するためにレイの向きと光の向きの内積を求めている
  float sundot = clamp(dot(raydirection,light),0.0,1.0);

  vec3 col;
  float dist=0.0;

  if (!trace(campos,raydirection,sundot, dist))
  {
    // 空のレンダリング

    //　レイの向きのy値を利用して空の色の補間を行う(上は青く、下は白くなるように)
    float t = pow(1.0-0.7*raydirection.y, 15.0);
    col = 0.8*(skybottom*t + skytop*(1.0-t));

    // 太陽光の考慮
    col += 0.47*vec3(1.0, 1.0, 1.0)*pow( sundot, 350.0 );
    // 太陽光の周りのぼんやりした光
    col += 0.4*vec3(0.7882, 0.702, 0.549)*pow( sundot, 2.0 );

    // 雲

    // 雲の動き
    vec2 shift = vec2( iTime*80.0, iTime*60.0 );

    // 雲の色と透明度
    vec4 sum = vec4(0,0,0,0); 
    for (int i=0; i<25; i++)
    {
      float cloudheight = (float(i)*12.0+350.0-campos.y) / raydirection.y;
      vec3 cloudposition = campos + cloudheight*raydirection + vec3(831.0, 321.0+float(i)*.15-shift.x*0.2, 1330.0+shift.y*3.0);
      float alpha = smoothstep(0.5, 1.0, fbm31( cloudposition*0.0015 ))*.9;
      vec3 localcolor = mix(vec3( 1.1, 1.05, 1.0 ), 0.5*vec3(0.8118, 0.9804, 1.0), alpha);
      alpha = (1.0-sum.w)*alpha;
      sum += vec4(localcolor*alpha, alpha);

      if (sum.w>0.98)
        break;
    }
    float alpha = smoothstep(0.7, 1.0, sum.w);
    sum.rgb /= sum.w+0.0001;

    // これは重要な部分で、太陽の前（または近く）にある密な雲の部分を暗くする
    // （雲自体の影をシミュレートする）
    sum.rgb -= 0.6*vec3(0.8, 0.75, 0.7)*pow(sundot,13.0)*alpha;
    // これは雲の低密度部分（エッジ）を明るくする（霧の中での光の散乱をシミュレートする）
    sum.rgb += 0.2*vec3(1.3, 1.2, 1.0)* pow(sundot,5.0)*(1.0-alpha);

    col = mix( col, sum.rgb , sum.w*(1.0-t) );
  }
  else
  {
    // 水のレンダリング

    // レイが水面にぶつかるときの位置ベクトル
    vec3 wpos = campos + dist * raydirection;

    // 水面の反射のための値
    vec2 xdiff = vec2(0.1, 0.0)*wavegain*4.;
    vec2 ydiff = vec2(0.0, 0.1)*wavegain*4.;

    // レイの向きを反射角で上書き
    raydirection = reflect(raydirection, normalize(vec3(water(wpos.xz-xdiff) - water(wpos.xz+xdiff), 1.0, water(wpos.xz-ydiff) - water(wpos.xz+ydiff))));  
    float refl = 1.0-clamp(dot(raydirection,vec3(0.0, 1.0, 0.0)),0.0,1.0);

    // 水面からの霧の影響の計算
    float sh = smoothstep(0.2, 1.0, trace_fog(wpos+20.0*raydirection,raydirection))*.7+.3;

    // 反射角が低いほど、水はより多く反射する
    float wsky   = refl*sh;     // 空の色の反射の強さ
    float wwater = (1.0-refl)*sh; // 水の色の強さ

    // 反射した太陽光の計算
    float sundot = clamp(dot(raydirection,light),0.0,1.0);

    // 水の色の設定
    col = wsky*reflskycolor;
    col += wwater*watercolor;
    col += vec3(.003, .005, .005) * (wpos.y-waterlevel+30.);

    // 太陽光
    float wsunrefl = wsky*(0.5*pow( sundot, 10.0 )+0.25*pow( sundot, 3.5)+.75*pow( sundot, 300.0));
    col += vec3(1.0,1.0,1.0)*wsunrefl; // sun reflection

    // 霧の色設定
    float fo = 1.0-exp(-pow(0.0003*dist, 1.5));
    vec3 fco = fogcolor + 0.6*vec3(1.0, 0.8314, 0.5569)*pow( sundot, 4.0 );
    col = mix( col, fco, fo );
  }

  fragColor=vec4(col,1.0);
}
